/* Full lessons for the start page's daily DevOps snippet, keyed by the snippet's title.
   Each one: lab (which practice terminal to open), more (paragraphs after the snippet's own
   text), steps ([what to do, command]: every command works in that lab), quiz ([question, answer]).
   Labs: linux bash git k8s net containers security backups ci iac pi (see cluster/sandbox/).
   In the k8s lab kubectl can read the whole cluster (not Secrets) and change only "playground". */
window.LESSONS = {
"Deployments keep your pods alive": { lab: "k8s",
  more: ["A Deployment doesn't run pods directly. It makes a ReplicaSet, and the ReplicaSet makes the pods. Each time you change the pod template (a new image, an env var), the Deployment makes a new ReplicaSet and slowly moves pods over to it. That's a rolling update.",
    "This loop of \"compare what I want with what exists, then fix the difference\" is called reconciliation. Almost everything in Kubernetes works this way, which is why you describe the end state instead of giving step-by-step orders."],
  steps: [["See every Deployment and how many of its pods are ready", "kubectl get deployments -A"],
    ["See the ReplicaSets behind your site", "kubectl -n graysoncodes get rs"],
    ["Make your own and watch it heal: delete a pod and see a new one appear", "kubectl create deployment heal --image=nginxinc/nginx-unprivileged:1.28-alpine && sleep 10 && kubectl delete pod -l app=heal && kubectl get pods -l app=heal"]],
  quiz: ["You delete a pod that belongs to a Deployment with replicas: 1. What happens?", "The ReplicaSet notices it has 0 of 1 pods and makes a new one, usually within seconds. To really stop it, scale the Deployment to 0 or delete the Deployment."] },

"Readiness vs liveness probes": { lab: "k8s",
  more: ["Readiness: \"can this pod take traffic right now?\" If it fails, the pod is taken out of its Service's endpoints but left running. Liveness: \"is this pod stuck forever?\" If it fails, the kubelet kills and restarts the container. Startup probes give slow apps time before liveness starts checking.",
    "The classic mistake is a liveness probe that checks a database. When the database has a blip, every pod restarts at once, which makes things worse. Liveness should only check the process itself."],
  steps: [["See which of your apps have readiness probes", "kubectl get deploy -A -o custom-columns=NS:.metadata.namespace,NAME:.metadata.name,READY-PROBE:.spec.template.spec.containers[0].readinessProbe.httpGet.path"],
    ["Look at the start page's probe", "kubectl -n start describe deploy start | grep -A2 Readiness"],
    ["Endpoints only list ready pods", "kubectl -n start get endpoints start"]],
  quiz: ["Your app takes 60 seconds to start and has a liveness probe that starts after 10 seconds. What goes wrong?", "It gets killed before it finishes starting, over and over (CrashLoopBackOff). Use a startupProbe or a longer initialDelaySeconds."] },

"Requests and limits": { lab: "k8s",
  more: ["The scheduler only looks at requests: a pod goes on a node whose requests still fit. Limits are enforced at run time by the kernel. Going over the CPU limit just slows you down (throttling); going over the memory limit gets the container killed (OOMKilled).",
    "Set memory requests close to what the app really uses and a limit a bit above. On small Pis it's often better to skip CPU limits and only set CPU requests, so apps can use spare CPU when it's free."],
  steps: [["What's using the most memory right now", "kubectl top pods -A --sort-by=memory | head -15"],
    ["What each node has promised away (requests) vs its size", "kubectl describe node raspberrypi | grep -A8 'Allocated resources'"],
    ["The playground hands out default limits: see them", "kubectl describe limitrange playground"]],
  quiz: ["A pod's memory limit is 64Mi and it tries to use 80Mi. What happens? And if it's CPU instead?", "Memory: the container is killed (OOMKilled) and restarted. CPU: it's throttled (slowed down), not killed."] },

"Every Service gets a DNS name": { lab: "net",
  more: ["CoreDNS runs in kube-system and answers for the cluster.local domain. A Service called web in namespace graysoncodes is web.graysoncodes.svc.cluster.local, and from inside the same namespace just \"web\" works, thanks to the search domains in each pod's /etc/resolv.conf.",
    "The name points at the Service's ClusterIP, a virtual IP that stays the same while pods come and go. kube-proxy turns traffic to that IP into traffic to one of the ready pods."],
  steps: [["Look up your site's Service by its full name", "dig +short web.graysoncodes.svc.cluster.local"],
    ["See the search domains that make short names work", "cat /etc/resolv.conf"],
    ["The short form works too, thanks to the search list", "getent hosts web.graysoncodes"]],
  quiz: ["From a pod in namespace ledger, what's the shortest name that reaches the web Service in graysoncodes?", "web.graysoncodes (plain \"web\" only works from inside graysoncodes)."] },

"Rollouts have an undo button": { lab: "k8s",
  more: ["Each revision is an old ReplicaSet kept around (scaled to 0). rollout undo just scales the previous one back up and the current one down. revisionHistoryLimit (10 by default) decides how many are kept.",
    "Undo only covers the Deployment's pod template. It won't bring back a deleted ConfigMap, a database migration, or data your new version changed. That's why backups and backwards-compatible changes still matter."],
  steps: [["Your site's rollout history", "kubectl -n graysoncodes rollout history deployment web"],
    ["Try it yourself: make a deployment, change it, undo it", "kubectl create deployment undo --image=nginxinc/nginx-unprivileged:1.28-alpine && kubectl set image deploy/undo nginx-unprivileged=nginxinc/nginx-unprivileged:1.29-alpine && kubectl rollout status deploy/undo"],
    ["Then undo and check the image", "kubectl rollout undo deploy/undo && kubectl get deploy undo -o jsonpath='{..image}'; echo"]],
  quiz: ["Does kubectl rollout undo restore a ConfigMap you edited?", "No. It only rolls back the Deployment's pod template. ConfigMaps, Secrets and data aren't versioned by the rollout."] },

"ConfigMaps hold config, not code": { lab: "k8s",
  more: ["A ConfigMap can reach a pod two ways: as environment variables, or as files in a mounted folder. Env vars are read once at start, so changes need a restart. Mounted folders do update (after a minute or so), except when mounted with subPath, which is the gotcha you hit with Homepage.",
    "ConfigMaps are limited to 1 MiB, so they're for settings and small files. Your start page fits easily."],
  steps: [["The ConfigMaps behind your start page", "kubectl -n start get configmap"],
    ["How the page is mounted (look for subPath)", "kubectl -n start get deploy start -o yaml | grep -B2 -A2 subPath"],
    ["Make one in the playground and read it back", "kubectl create configmap demo --from-literal=greeting=hi && kubectl get cm demo -o yaml"]],
  quiz: ["You change a ConfigMap that a pod reads as environment variables. When does the pod see it?", "Only after the pod restarts (for example kubectl rollout restart). Env vars are set when the container starts."] },

"Secrets are only base64": { lab: "security",
  more: ["Base64 is an encoding, like writing a word in Morse code: anyone can turn it back. Secrets are protected by who's allowed to read them (RBAC), and optionally by encrypting them at rest in the datastore.",
    "Never paste a Secret's YAML into Git, chat or a screenshot. Tools like Sealed Secrets or SOPS let you commit an encrypted version that only the cluster can open."],
  steps: [["Encode and decode something yourself", "printf 'hunter2' | base64; printf 'aHVudGVyMg==' | base64 -d; echo"],
    ["Decode the practice Secret (this is a lab mission)", "grep password: ~/files/secret.yaml | awk '{print $2}' | base64 -d; echo"],
    ["Your lab can't read real Secrets: RBAC says no", "kubectl auth can-i get secrets -n ledger"]],
  quiz: ["Is a Kubernetes Secret encrypted?", "Not by default, it's only base64-encoded. Access is controlled with RBAC; encryption at rest is an extra setting."] },

"Where your data actually lives": { lab: "k8s",
  more: ["A PVC is a request (\"I need 5Gi\"). A PersistentVolume is the actual storage that satisfies it. k3s's local-path provisioner makes a folder under /var/lib/rancher/k3s/storage on whichever node the pod first ran on, and pins the pod to that node from then on.",
    "That's simple and fast, but if that Pi's SD card dies, the data goes with it. That's why your nightly B2 backups matter, and why bigger setups use network storage like Longhorn or NFS."],
  steps: [["Every claim in the cluster", "kubectl get pvc -A"],
    ["The volumes behind them, and which node each lives on", "kubectl get pv -o custom-columns=NAME:.metadata.name,CLAIM:.spec.claimRef.name,NODE:.spec.nodeAffinity.required.nodeSelectorTerms[0].matchExpressions[0].values[0]"],
    ["The storage class that makes them", "kubectl get storageclass"]],
  quiz: ["Your Ledger PVC is local-path on the Pi 5. Can the Ledger pod move to the Pi 4 if the Pi 5 dies?", "No. The volume is a folder on the Pi 5's disk, so the pod is pinned there. You'd restore from backup instead."] },

"Namespaces are folders for your apps": { lab: "k8s",
  more: ["Namespaces group things and scope names: two apps can both have a Service called web if they're in different namespaces. RBAC, quotas and network policies are usually set per namespace, which is exactly how your playground is fenced off.",
    "Some things aren't in any namespace: nodes, PersistentVolumes, StorageClasses, ClusterRoles and namespaces themselves."],
  steps: [["All namespaces", "kubectl get ns"],
    ["Which kinds of things live in namespaces and which don't", "kubectl api-resources --namespaced=false | head -15"],
    ["The fence around your playground", "kubectl describe ns playground; kubectl describe quota -n playground"]],
  quiz: ["What happens to the pods, Services and PVCs inside a namespace when you delete it?", "They're all deleted with it. (PVC data may be deleted too, depending on the volume's reclaim policy.)"] },

"Labels glue everything together": { lab: "k8s",
  more: ["A label is a key/value tag on an object, like app=web. A selector picks objects by labels. Deployments find their pods by selector, Services send traffic to pods by selector, and kubectl -l filters by selector.",
    "If you relabel a pod so it no longer matches, the Deployment thinks it's gone and makes a new one, and the old pod keeps running on its own. That's a handy trick for debugging a misbehaving pod without it getting traffic."],
  steps: [["Pods and their labels", "kubectl get pods -A --show-labels | head -15"],
    ["The web Service's selector", "kubectl -n graysoncodes get svc web -o jsonpath='{.spec.selector}'; echo"],
    ["Filter with a selector", "kubectl get pods -A -l app=web"]],
  quiz: ["A Service has selector app=api but the pods are labelled app=API. What do you see?", "The Service has no endpoints, so connections fail or hang, with no error anywhere. Labels are case-sensitive."] },

"Events tell you why": { lab: "k8s",
  more: ["Events are short notes the cluster writes as things happen: Scheduled, Pulling, Started, BackOff, FailedScheduling, Unhealthy. They only last about an hour, so look soon after a problem.",
    "kubectl describe shows a pod's events at the bottom, which is usually the fastest way to answer \"why is this pod not running?\""],
  steps: [["The latest events in the whole cluster", "kubectl get events -A --sort-by=.lastTimestamp | tail -20"],
    ["Make a broken pod on purpose", "kubectl run oops --image=nginx:does-not-exist"],
    ["Read why it's stuck", "sleep 5; kubectl describe pod oops | tail -8"]],
  quiz: ["A pod is Pending forever. Where do you look first?", "kubectl describe pod <name> and read the Events: it usually says FailedScheduling with the reason (not enough memory, no matching node, PVC not bound)."] },

"A flowchart for broken deployments": { lab: "k8s",
  more: ["The flowchart works from the pod outwards: are pods running? Are they ready? Does the Service have endpoints? Does the Ingress or tunnel point at the Service? Each question has one kubectl command that answers it.",
    "Following the same order every time is the real skill. It turns \"the site is down\" into a short list of checks instead of guessing."],
  steps: [["Step 1: anything not Running?", "kubectl get pods -A | grep -v Running"],
    ["Step 2: does the Service have endpoints?", "kubectl -n graysoncodes get endpoints"],
    ["Step 3: can you reach it from inside?", "curl -sI http://web.graysoncodes | head -1"]],
  quiz: ["Pods are Running and Ready, but the site still doesn't load. What's the next thing to check?", "The Service: does it have endpoints (selector and port match the pods)? Then whatever is in front of it (here, the Cloudflare tunnel route)."] },

"DaemonSets run one pod per node": { lab: "k8s",
  more: ["DaemonSets are for node-level jobs: log collectors, monitoring agents, network plugins, storage drivers. In k3s, svclb (the built-in load balancer) is also a DaemonSet.",
    "Unlike Deployments you don't set replicas; the count is the number of nodes that match. Taints and nodeSelectors decide which nodes get one."],
  steps: [["All DaemonSets and how many nodes they cover", "kubectl get daemonsets -A"],
    ["Which node each CrowdSec agent is on", "kubectl get pods -A -o wide | grep -i crowdsec"],
    ["The nodes they could run on", "kubectl get nodes"]],
  quiz: ["You add a third Pi to the cluster. What happens to the CrowdSec agent DaemonSet?", "It automatically starts one more agent pod on the new Pi."] },

"CronJobs are cron for the cluster": { lab: "k8s",
  more: ["A CronJob makes a Job on a schedule; the Job makes pods until one succeeds (up to backoffLimit tries). Schedules use cron syntax, and the timeZone field lets you say America/Chicago instead of UTC.",
    "Your off-site backups are CronJobs too. You can start a run by hand with kubectl create job --from=cronjob/<name> to test one without waiting for 4am."],
  steps: [["All scheduled jobs, with their schedules and last run", "kubectl get cronjobs -A"],
    ["Recent runs", "kubectl get jobs -A --sort-by=.metadata.creationTimestamp | tail -8"],
    ["Make your own every-minute CronJob in the playground", "kubectl create cronjob tick --image=busybox:1.36 --schedule='*/1 * * * *' -- date && sleep 70 && kubectl get jobs"]],
  quiz: ["What does the schedule 30 4 * * * mean?", "Every day at 4:30 (in the CronJob's time zone)."] },

"Which Pi runs what?": { lab: "k8s",
  more: ["The scheduler picks a node for each new pod: it filters out nodes that can't take it (not enough room, wrong labels, taints) and scores the rest. You can steer it with nodeSelector, node affinity, taints and tolerations.",
    "Several of your apps are pinned on purpose: Jellyfin and the Ledger to the Pi 5 (more memory, their data lives there), Pi-hole to the Pi 4."],
  steps: [["Which node each pod is on", "kubectl get pods -A -o wide --sort-by=.spec.nodeName | awk '{print $8, $1, $2}' | column -t | head -40"],
    ["The labels you can select nodes by", "kubectl get nodes --show-labels"],
    ["Apps pinned with a nodeSelector", "kubectl get deploy -A -o custom-columns=NS:.metadata.namespace,NAME:.metadata.name,NODE:.spec.template.spec.nodeSelector"]],
  quiz: ["What's the difference between nodeSelector and a taint?", "nodeSelector is the pod saying \"I want nodes with this label\". A taint is the node saying \"keep away unless you tolerate me\"."] },

"Draining a node before maintenance": { lab: "pi",
  more: ["drain does two things: cordon (mark the node unschedulable so nothing new lands there) and evict (politely remove the pods so their controllers recreate them elsewhere). DaemonSet pods are skipped because they belong on every node.",
    "Pods with local-path data can't move, so on your cluster a drain of the Pi 5 stops those apps until it's back. After maintenance, kubectl uncordon lets pods schedule there again. This lab is the real Pi, so use --dry-run."],
  steps: [["Log in to the Pi 5 (the lab does this for you)", "ssh pi5"],
    ["See what a drain of the Pi 4 would do, without doing it", "kubectl drain pi2 --ignore-daemonsets --delete-emptydir-data --dry-run=client"],
    ["Cordon only marks it; uncordon undoes it", "kubectl get nodes"]],
  quiz: ["After draining and rebooting a Pi, what must you run before pods go back to it?", "kubectl uncordon <node>."] },

"Helm is a package manager": { lab: "k8s",
  more: ["A chart is a folder of templated YAML plus a values.yaml. helm install renders the templates with your values and applies them as a release, which you can upgrade, roll back and uninstall as one unit.",
    "k3s adds a HelmChart resource so you can describe a chart install in plain YAML; a small job runs helm for you. That's how your CrowdSec got installed."],
  steps: [["Charts k3s installed for you", "kubectl get helmcharts -A"],
    ["Make your own chart and look at it", "helm create mychart && ls mychart mychart/templates"],
    ["See what it would apply, without applying", "helm template demo ./mychart | head -40"]],
  quiz: ["What's the difference between helm template and helm install?", "template only prints the rendered YAML. install renders it and applies it to the cluster as a tracked release."] },

"What makes k3s small": { lab: "k8s",
  more: ["Upstream Kubernetes is several separate programs. k3s compiles the API server, scheduler, controller manager, kubelet and kube-proxy into one binary, swaps etcd for SQLite (via kine) on single servers, and drops cloud-provider code you don't need on a Pi.",
    "It also ships useful defaults: containerd, Flannel networking, CoreDNS, local-path storage, metrics-server, ServiceLB and Traefik (which you turned off in favour of your own nginx)."],
  steps: [["Your nodes, versions and container runtime", "kubectl get nodes -o wide"],
    ["The built-in add-ons running in kube-system", "kubectl -n kube-system get deploy,ds"],
    ["The API server's own health checks", "kubectl get --raw='/readyz?verbose' | tail -8"]],
  quiz: ["What does a single k3s server use instead of etcd by default?", "SQLite (through kine). etcd is used when you run several servers for high availability."] },

"Config belongs in the environment": { lab: "k8s",
  more: ["If settings are baked into the image, you need a new build for every environment. If they come from env vars (or mounted files), one image runs in dev, test and prod, and a config change is just a restart.",
    "Secrets follow the same rule but come from Secret objects, never from the image or the repo."],
  steps: [["The Ledger's environment settings", "kubectl -n ledger describe deploy ledger | grep -A8 Environment"],
    ["Env vars across your apps", "kubectl get deploy -A -o jsonpath='{range .items[*]}{.metadata.name}{\": \"}{.spec.template.spec.containers[0].env[*].name}{\"\\n\"}{end}'"],
    ["Try it: same image, different setting", "kubectl create deployment cfg --image=busybox:1.36 -- sh -c 'echo hello $NAME; sleep 3600' && kubectl set env deploy/cfg NAME=Grayson && sleep 15 && kubectl logs deploy/cfg"]],
  quiz: ["Why not put the production database password in the Dockerfile?", "Anyone with the image can read it, it ends up in Git, and changing it needs a rebuild. Pass it in at run time from a Secret."] },

"Logs are a stream": { lab: "k8s",
  more: ["The container runtime captures everything a container prints to stdout and stderr and writes it to a file on the node. kubectl logs reads that file through the kubelet, and log shippers (like CrowdSec's agent, or Loki's Promtail) tail the same files.",
    "Logs from a crashed container are still there with --previous, which is often the only way to see why it died."],
  steps: [["Your site's latest log lines", "kubectl -n graysoncodes logs deploy/web --tail=20"],
    ["Follow logs live (Ctrl+C to stop)", "kubectl -n graysoncodes logs deploy/web -f --tail=5"],
    ["Logs from every pod of an app at once", "kubectl -n graysoncodes logs -l app=web --prefix --tail=5"]],
  quiz: ["A pod is in CrashLoopBackOff. How do you see what it printed before the last crash?", "kubectl logs <pod> --previous."] },

"Git as the source of truth": { lab: "git",
  more: ["In GitOps, nobody runs kubectl apply by hand. You change YAML in Git, open a pull request, merge it, and a controller in the cluster (Argo CD or Flux) notices and applies it. If someone changes the cluster by hand, the controller puts it back.",
    "You get review, history and rollback (git revert) for free. Your cluster/k8s folder is already the first half of this; Argo CD is the other half."],
  steps: [["History of a file over time", "cd ~/repo && git log --oneline --follow -- index.html"],
    ["What exactly changed in a commit", "cd ~/repo && git show --stat HEAD"],
    ["Roll back a change the GitOps way: revert it", "cd ~/repo && git log --oneline | head -3"]],
  quiz: ["With Argo CD watching your repo, how do you roll back a bad change?", "git revert the commit and push. Argo CD syncs the cluster back to the reverted state."] },

"Blameless postmortems": { lab: "k8s",
  more: ["A postmortem has a timeline, the impact, the root causes (usually several), what went well, and action items with owners. \"Blameless\" means you ask why the system let a mistake happen, not who made it, so people stay honest.",
    "Writing one even for a homelab hiccup is great practice and great interview material."],
  steps: [["Your DNS server's recent logs (the CoreDNS hiccup lived here)", "kubectl -n kube-system logs deploy/coredns --tail=30"],
    ["Pods that restarted, and how often", "kubectl get pods -A --sort-by='.status.containerStatuses[0].restartCount' | tail -5"],
    ["Recent warnings worth a postmortem", "kubectl get events -A --field-selector type=Warning --sort-by=.lastTimestamp | tail"]],
  quiz: ["Name three sections every postmortem should have.", "Any three of: summary/impact, timeline, root causes, what went well, what went badly, action items with owners."] },

"SLOs: how up is up enough?": { lab: "net",
  more: ["SLI = what you measure (the share of requests that succeed in under 500 ms). SLO = your target for it (99.5% over 30 days). SLA = a promise to customers with a penalty. You set SLOs a bit stricter than any SLA.",
    "99.5% a month allows about 3.6 hours of downtime; 99.9% allows about 43 minutes. On two Pis on Wi-Fi, 99.5% is an honest goal."],
  steps: [["Measure one request: status and time", "curl -s -o /dev/null -w '%{http_code} %{time_total}s\\n' https://graysoncodes.org"],
    ["Measure 20 and count the good ones (200 in under 1s)", "for i in $(seq 20); do curl -s -o /dev/null -w '%{http_code} %{time_total}\\n' https://graysoncodes.org; done | awk '$1==200 && $2<1 {ok++} END {print ok \"/\" NR \" good\"}'"],
    ["How much downtime 99.5% allows per 30 days, in minutes", "echo '30*24*60*0.005' | bc"]],
  quiz: ["Your SLO is 99.9% per 30 days. Roughly how much downtime is that?", "About 43 minutes."] },

"The four golden signals": { lab: "k8s",
  more: ["Latency: how long requests take (watch the slow ones, not just the average). Traffic: how many requests. Errors: how many fail. Saturation: how full the resources are (CPU, memory, disk, queue length).",
    "Dashboards and alerts built around these four catch most real problems. Errors and latency affect users directly; traffic and saturation tell you why."],
  steps: [["Saturation: how busy each Pi is", "kubectl top nodes"],
    ["Saturation per app", "kubectl top pods -A --sort-by=cpu | head -10"],
    ["Traffic and errors: count status codes in your site's recent logs", "kubectl -n graysoncodes logs deploy/web --tail=500 | awk '{print $9}' | grep -E '^[0-9]{3}$' | sort | uniq -c"]],
  quiz: ["Which golden signal would warn you first that the Pi 4 is running out of memory?", "Saturation."] },

"Toil is work a script should do": { lab: "bash",
  more: ["Toil is manual, repetitive, automatable work that grows with your system and leaves nothing lasting behind. Google's SRE teams try to keep it under half their time.",
    "The fix is usually small: a script, a CronJob, a CI step. Your deploy.sh and setup.sh scripts are exactly this kind of win."],
  steps: [["Your most-used commands in this lab", "history | awk '{print $2}' | sort | uniq -c | sort -rn | head"],
    ["Turn a repeated chore into a script", "printf '#!/bin/bash\\nset -euo pipefail\\ndate\\ndf -h / | tail -1\\nuptime\\n' > ~/scripts/health.sh && bash ~/scripts/health.sh"],
    ["Check it for bugs", "shellcheck ~/scripts/health.sh && echo clean"]],
  quiz: ["Is writing a new feature toil?", "No. Toil is repetitive operational work with no lasting value. Feature work, and automating toil away, is engineering."] },

"Error budgets": { lab: "net",
  more: ["The error budget is 100% minus your SLO. While budget is left, ship freely and experiment. When it's spent, slow down and work on reliability until it recovers.",
    "This turns \"should we ship this risky change?\" from an argument into a number both developers and operators agreed on."],
  steps: [["Minutes of budget per 30 days at 99.5%", "echo '30*24*60*(1-0.995)' | bc"],
    ["How long has this container's Pi been up?", "uptime"],
    ["Check your site right now", "curl -s -o /dev/null -w '%{http_code}\\n' https://graysoncodes.org"]],
  quiz: ["Your budget for the month is spent. What changes?", "You pause risky releases and spend time on reliability until the budget recovers."] },

"How DNS updates really spread": { lab: "net",
  more: ["Every answer has a TTL (time to live). Resolvers cache it for that long, so after you change a record, some people see the old answer until their cache expires. Negative answers (\"no such name\") are cached too.",
    "Before a planned change, lower the TTL a day ahead so the switch spreads quickly."],
  steps: [["Ask your Pi-hole; the number is the TTL left in seconds", "dig graysoncodes.org @192.168.1.36 +noall +answer"],
    ["Ask again: the TTL counts down because it's cached", "sleep 5; dig graysoncodes.org @192.168.1.36 +noall +answer"],
    ["Ask Cloudflare's servers directly (the source of truth)", "dig graysoncodes.org @$(dig +short NS graysoncodes.org | head -1) +noall +answer"]],
  quiz: ["You change a record whose TTL was 3600. How long might some people still see the old value?", "Up to about an hour (3600 seconds), longer if a resolver ignores TTLs."] },

"Tunnels instead of open ports": { lab: "k8s",
  more: ["cloudflared opens outbound connections to Cloudflare's edge and keeps them open. When someone visits your site, Cloudflare sends the request down that connection, and cloudflared forwards it to a Service in the cluster.",
    "Nothing listens on your home IP, so port scans of your house find nothing, and Cloudflare's firewall and CrowdSec's bouncer sit in front of everything."],
  steps: [["The tunnel's pods", "kubectl -n graysoncodes get pods -l app=cloudflared -o wide"],
    ["Its recent logs: look for registered connections", "kubectl -n graysoncodes logs deploy/cloudflared --tail=10"],
    ["Where it sends traffic: the web Service", "kubectl -n graysoncodes get svc web"]],
  quiz: ["Why don't you need port forwarding on the router for graysoncodes.org?", "cloudflared makes outbound connections to Cloudflare, and requests come back down them. Nothing needs to connect in to your house."] },

"What DNS actually does": { lab: "net",
  more: ["A lookup goes from your device to a resolver (your Pi-hole), which asks the root servers, then the .org servers, then the domain's own name servers, caching each answer. Record types: A (IPv4), AAAA (IPv6), CNAME (alias), MX (mail), TXT (anything, often verification).",
    "Pi-hole sits in the resolver spot and answers 0.0.0.0 for ad and tracker domains, so the request never happens."],
  steps: [["Follow a lookup from the root down", "dig +trace graysoncodes.org | tail -15"],
    ["Ask your Pi-hole about an ad domain", "dig @192.168.1.36 doubleclick.net +short"],
    ["Different record types", "dig +short graysoncodes.org MX; dig +short graysoncodes.org TXT | head -3"]],
  quiz: ["What does Pi-hole answer for a blocked domain?", "0.0.0.0 (an address that goes nowhere), so the ad never loads."] },

"Reverse proxies": { lab: "net",
  more: ["A forward proxy acts for clients (like a school web filter). A reverse proxy acts for servers: clients talk to it, and it picks which backend answers. It's the natural place for TLS, compression, caching, rate limits and access logs.",
    "Your web nginx routes by path (/blog to Flask) and by host name (dnd. to the Ledger)."],
  steps: [["Ask the front door for the home page", "curl -sI http://web.graysoncodes -H 'Host: graysoncodes.org' | head -3"],
    ["Same front door, /blog is answered by Flask behind it", "curl -sI http://web.graysoncodes/blog -H 'Host: graysoncodes.org' | head -3"],
    ["Same front door, different host name: the Ledger", "curl -sI http://web.graysoncodes/ -H 'Host: dnd.graysoncodes.org' | head -3"]],
  quiz: ["Name two jobs a reverse proxy often does besides routing.", "Any two: TLS, caching, compression, rate limiting, logging, authentication, load balancing."] },

"Multi-stage builds": { lab: "containers",
  more: ["Each FROM starts a new stage. Later stages can COPY --from=<stage> just the files they need. Compilers, node_modules and build caches stay in the build stage and never ship.",
    "Smaller images pull faster on Pis, have fewer packages with CVEs, and start quicker."],
  steps: [["Your web image only has the final stage's layers: count them", "skopeo inspect --override-os linux --override-arch arm64 docker://ghcr.io/g39832/portfolio-web:latest | jq '.Layers | length'"],
    ["Write your own two-stage Dockerfile (lab mission 6)", "learn 6"],
    ["Lint it", "hadolint ~/app/Dockerfile.multi"]],
  quiz: ["In a multi-stage build, which stage becomes the final image?", "The last one (unless you pick another with --target)."] },

"Dockerfile best practices": { lab: "containers",
  more: ["Each instruction is a cached layer. If a layer changes, every layer after it rebuilds, so put rarely-changing things (base image, system packages, dependencies) first and your code last.",
    "Also: pin the base image, clean package caches in the same RUN, use COPY not ADD, run as a non-root USER, and use a .dockerignore."],
  steps: [["Lint the beginner Dockerfile", "hadolint ~/app/Dockerfile"],
    ["Read the mission that fixes the order", "learn 4"],
    ["Check your progress", "learn"]],
  quiz: ["Why copy requirements.txt and install before copying the rest of the code?", "So editing your code doesn't invalidate the cached dependency-install layer, making rebuilds much faster."] },

"What a container really is": { lab: "containers",
  more: ["Namespaces give a process its own view: its own PIDs (it's PID 1), its own network, its own hostname and its own filesystem root. Cgroups limit how much CPU and memory it can use. The image is just the filesystem it starts with.",
    "So there's no little virtual machine: your Pi's kernel runs every container directly."],
  steps: [["PID 1 in here is the terminal server, not an operating system", "ps aux | head"],
    ["Your own hostname: it's the pod's name", "hostname; cat /etc/hostname"],
    ["The memory limit Kubernetes set, enforced by a cgroup", "cat /sys/fs/cgroup/memory.max"]],
  quiz: ["Does a container have its own kernel?", "No. All containers on a host share the host's kernel; namespaces and cgroups isolate them."] },

"Reading a GitHub Actions workflow": { lab: "ci",
  more: ["on: lists the triggers (push, pull_request, schedule, workflow_dispatch). jobs: run in parallel on fresh runners unless one needs another. steps: run in order, either uses: (a ready-made action) or run: (shell commands).",
    "A matrix runs the same job for several values; your cluster-images workflow builds web, blog and sandbox that way."],
  steps: [["Read your real workflow", "cat ~/real/cluster-images.yml"],
    ["Find the matrix", "grep -n -A3 matrix ~/real/cluster-images.yml"],
    ["Lint a workflow", "actionlint ~/real/cluster-images.yml && echo clean"]],
  quiz: ["What does workflow_dispatch in on: let you do?", "Run the workflow by hand from the Actions tab (or gh workflow run)."] },

"Pin your versions": { lab: "k8s",
  more: ["Semantic versioning: MAJOR.MINOR.PATCH. Patch = bug fixes, minor = new features that don't break things, major = breaking changes. Pinning to 1.28 gets you patch updates when you pull; pinning to 1.28.0 or a digest gets you exactly that build.",
    "Tools like Renovate open pull requests when new versions come out, so you upgrade on purpose instead of by surprise."],
  steps: [["Every image the cluster runs", "kubectl get pods -A -o jsonpath='{..image}' | tr ' ' '\\n' | sort -u"],
    ["Find any :latest tags", "kubectl get pods -A -o jsonpath='{..image}' | tr ' ' '\\n' | sort -u | grep -E ':latest$|^[^:]+$'"],
    ["Sort versions correctly", "printf '1.9.7\\n1.10.0\\n1.2.3\\n' | sort -V"]],
  quiz: ["Going from 2.4.1 to 3.0.0, what should you expect?", "Breaking changes. Read the release notes before upgrading a major version."] },

"Scan images for known holes": { lab: "containers",
  more: ["Scanners like Trivy list every package in an image and match versions against vulnerability databases. Most findings come from the base image, which is another reason to use small, pinned, regularly-updated bases.",
    "A good habit: scan in CI and fail the build on CRITICAL findings that have a fix available. Trivy needs a big database download, so this lab looks at images with skopeo, and you can run Trivy on the real Pi."],
  steps: [["What's inside a published image (OS, layers, labels)", "skopeo inspect --override-os linux --override-arch arm64 docker://nginxinc/nginx-unprivileged:1.28-alpine | jq '{Created, Os, Architecture, Layers: (.Layers|length)}'"],
    ["Which tags exist, so you can pick a newer patch", "skopeo list-tags docker://nginxinc/nginx-unprivileged | jq -r '.Tags[]' | grep -E '^1\\.2[89].*alpine$' | tail"],
    ["On the real Pi 5 (pi lab), scan it with Trivy", "echo 'docker run --rm aquasec/trivy image --severity HIGH,CRITICAL nginxinc/nginx-unprivileged:1.28-alpine'"]],
  quiz: ["Where do most vulnerabilities in a typical image come from?", "The base image's OS packages, not your own code."] },

"Secrets you can commit": { lab: "security",
  more: ["Sealed Secrets runs a controller with a private key in your cluster. kubeseal encrypts a normal Secret with the public key into a SealedSecret. Only the controller can turn it back into a Secret, so the encrypted YAML is safe to commit.",
    "SOPS is the other popular option: it encrypts just the values in a YAML file, using age or a cloud KMS key."],
  steps: [["Why plain Secrets can't go in Git: anyone can decode them", "cat ~/files/secret.yaml"],
    ["Encrypt and decrypt a file with a password, the basic idea", "openssl enc -aes-256-cbc -pbkdf2 -in ~/files/secret.yaml -out /tmp/s.enc -pass pass:demo && head -c 64 /tmp/s.enc | base64 && openssl enc -d -aes-256-cbc -pbkdf2 -in /tmp/s.enc -pass pass:demo | head -3"],
    ["Find secrets that leaked into files", "grep -rnE 'AKIA|password|token' ~/project"]],
  quiz: ["With Sealed Secrets, who can decrypt the file in your repo?", "Only the controller in your cluster, which holds the private key."] },

"The 3-2-1 rule": { lab: "backups",
  more: ["Three copies (the live data plus two backups), on two kinds of storage (SD card and cloud, say), one off-site (B2). Your nightly restic jobs give the Ledger and blog an off-site copy; a USB drive on the Pi would make it 3-2-1.",
    "And test restores. A backup only counts once you've restored from it, which you did with restore.sh."],
  steps: [["Look at a backup repository's snapshots", "restic -r ~/old-backups snapshots"],
    ["Restore one file from it (lab mission 2)", "learn 2"],
    ["Check the repository's health", "restic -r ~/old-backups check"]],
  quiz: ["You have the live database plus a copy in another folder on the same SD card. How far are you from 3-2-1?", "That's 2 copies on 1 medium with 0 off-site. You need a third copy, a second kind of storage, and one copy somewhere else."] },

"Ansible: rebuild a Pi from a file": { lab: "iac",
  more: ["An inventory lists your machines. A playbook lists tasks using modules (apt, copy, file, service, user). Ansible connects over SSH, checks each task's current state, and only changes what's different, so running it twice is safe.",
    "Rebuilding a Pi becomes: flash the card, run one playbook."],
  steps: [["The inventory and playbook", "cat ~/ansible/inventory.ini ~/ansible/site.yml"],
    ["Run it", "ansible-playbook -i ~/ansible/inventory.ini ~/ansible/site.yml"],
    ["Run it again: changed=0 is idempotence", "ansible-playbook -i ~/ansible/inventory.ini ~/ansible/site.yml | tail -2"]],
  quiz: ["What does idempotent mean?", "Running it again changes nothing if everything is already in the wanted state."] },

"Terraform describes infrastructure": { lab: "iac",
  more: ["You declare resources in .tf files. plan compares them with the state file (what Terraform made last time) and the real world, and shows what it will add, change or destroy. apply does it. Providers (Cloudflare, AWS, local files) do the API calls.",
    "OpenTofu is the open-source fork with the same language, and it's what this lab uses."],
  steps: [["The config", "cat ~/tofu/main.tf"],
    ["Download the provider and plan", "cd ~/tofu && tofu init && tofu plan"],
    ["Apply, then look at the state", "cd ~/tofu && tofu apply -auto-approve && tofu state list"]],
  quiz: ["What's the state file for?", "It records what Terraform/OpenTofu created, so the next plan knows what exists and what to change."] },

"Prometheus metric types": { lab: "k8s",
  more: ["Counter: only goes up (requests served); you graph its rate. Gauge: goes up and down (memory in use). Histogram: counts observations into buckets (request durations), so you can compute percentiles like p95. Summary: like a histogram but percentiles computed in the app.",
    "Prometheus scrapes /metrics pages on a schedule and stores them as time series with labels."],
  steps: [["metrics-server's view of node resources (gauges)", "kubectl top nodes"],
    ["The raw metrics API behind it", "kubectl get --raw /apis/metrics.k8s.io/v1beta1/nodes | jq '.items[] | {name: .metadata.name, usage}'"],
    ["On the real Pi 5 (pi lab): node-exporter's metrics", "echo 'curl -s localhost:9100/metrics | grep -v \"^#\" | head -20'"]],
  quiz: ["Is \"total HTTP requests served\" a counter or a gauge?", "A counter: it only goes up (until a restart resets it). You graph its rate."] },

"systemd runs your services": { lab: "pi",
  more: ["A unit file says what to run, as which user, when to start it, and whether to restart it. systemctl start/stop/restart/enable/disable controls it; journalctl -u <unit> shows its logs.",
    "On your Pi 5, k3s itself, Tailscale and the old Pi-hole are systemd units. Containers don't run systemd, so this lesson uses the real Pi."],
  steps: [["Log in to the Pi 5 (the lab does this for you)", "ssh pi5"],
    ["Anything failed?", "systemctl --failed"],
    ["k3s's status and its last log lines", "systemctl status k3s --no-pager | head -5; journalctl -u k3s -n 10 --no-pager"]],
  quiz: ["What's the difference between systemctl start and systemctl enable?", "start runs it now. enable makes it start at boot. (enable --now does both.)"] },

"Branching, visually": { lab: "git",
  more: ["A branch is just a movable label pointing at a commit. Committing moves the current branch forward. Merging makes a commit with two parents; rebasing replays your commits on top of another branch so history is a straight line.",
    "git log --graph draws the same picture the Learn Git Branching game shows."],
  steps: [["Draw the practice repo's history", "cd ~/repo && git log --oneline --graph --all"],
    ["Make a branch and a commit, then draw again", "cd ~/repo && git switch -c try && echo x > try.txt && git add try.txt && git commit -m try && git log --oneline --graph --all"],
    ["Go back to main", "cd ~/repo && git switch main"]],
  quiz: ["What is a branch, really?", "A name that points at one commit, and moves forward when you commit on it."] },

"Running an incident": { lab: "k8s",
  more: ["During an incident: one person leads, someone communicates, and the goal is to stop the damage first (roll back, fail over) and find the root cause later. Write a timeline as you go.",
    "Afterwards, write the postmortem while it's fresh."],
  steps: [["First look: what's not running?", "kubectl get pods -A --field-selector=status.phase!=Running"],
    ["What changed recently?", "kubectl get events -A --sort-by=.lastTimestamp | tail -15"],
    ["Are the nodes healthy?", "kubectl get nodes; kubectl top nodes"]],
  quiz: ["The site broke right after a deploy. Fix the cause or roll back first?", "Roll back first to stop the damage, then find the cause calmly."] },

"Continuous delivery": { lab: "git",
  more: ["Continuous integration: merge small changes often and test each one automatically. Continuous delivery: every passing change could go to production at the push of a button. Continuous deployment: it goes automatically.",
    "Small batches mean each change is easy to review, easy to test, and easy to undo."],
  steps: [["How many commits in the last week", "cd ~/repo && git log --since='1 week ago' --oneline | wc -l"],
    ["How big each commit is", "cd ~/repo && git log --stat --oneline | head -20"],
    ["Tag a release", "cd ~/repo && git tag -a v0.1.0 -m 'first' 2>/dev/null; git tag"]],
  quiz: ["What's the difference between continuous delivery and continuous deployment?", "Delivery: always ready to release, a person presses the button. Deployment: every passing change ships automatically."] },

"Feature toggles": { lab: "bash",
  more: ["A toggle is an if-statement around new code, controlled by config (an env var, a file, a flag service). You deploy with it off, turn it on for yourself, then for everyone. If it misbehaves, turn it off: no rollback needed.",
    "Remove toggles once a feature is settled, or they pile up as clutter."],
  steps: [["A tiny toggle in bash", "printf '#!/bin/bash\\nif [ \"${NEW_GREETING:-off}\" = on ]; then echo \"Hey there!\"; else echo Hello.; fi\\n' > ~/scripts/toggle.sh"],
    ["Off by default", "bash ~/scripts/toggle.sh"],
    ["Turn it on without changing the code", "NEW_GREETING=on bash ~/scripts/toggle.sh"]],
  quiz: ["How is \"deploy\" different from \"release\" with feature toggles?", "Deploy puts the code on the servers (turned off). Release is flipping the toggle so users get it."] },

"Blue-green deployments": { lab: "k8s",
  more: ["Blue is live. You start green (the new version) next to it and test it. Then you switch the router (in Kubernetes, the Service's selector) from blue to green in one step. Blue stays up for a quick switch back.",
    "It costs double the resources during the switch, which is the trade-off on small Pis."],
  steps: [["Make blue and green", "kubectl create deployment blue --image=nginxinc/nginx-unprivileged:1.28-alpine && kubectl create deployment green --image=nginxinc/nginx-unprivileged:1.29-alpine"],
    ["A Service pointing at blue", "kubectl create service clusterip live --tcp=80:8080 && kubectl set selector svc live app=blue && sleep 10 && curl -sI http://live.playground | grep -i server"],
    ["Switch everyone to green in one step", "kubectl set selector svc live app=green && sleep 2 && curl -sI http://live.playground | grep -i server"]],
  quiz: ["How do you roll back a blue-green switch?", "Point the router (the Service selector) back at blue, which is still running."] },

"Canary releases": { lab: "k8s",
  more: ["The simple Kubernetes way: two Deployments with the same app label behind one Service, say 9 old pods and 1 new. About 10% of requests hit the canary. Watch its errors and latency, then grow it or kill it.",
    "Service meshes and tools like Argo Rollouts make the percentages exact and automate the watching."],
  steps: [["Stable: 3 old pods", "kubectl create deployment stable --image=nginxinc/nginx-unprivileged:1.28-alpine --replicas=3 && kubectl label deploy stable track=stable"],
    ["Canary: 1 new pod with the same app label", "kubectl create deployment canary --image=nginxinc/nginx-unprivileged:1.29-alpine && kubectl patch deploy canary -p '{\"spec\":{\"template\":{\"metadata\":{\"labels\":{\"tier\":\"site\"}}}}}' && kubectl patch deploy stable -p '{\"spec\":{\"template\":{\"metadata\":{\"labels\":{\"tier\":\"site\"}}}}}'"],
    ["One Service for both; count which version answers", "kubectl create service clusterip site --tcp=80:8080 && kubectl set selector svc site tier=site && sleep 15 && for i in $(seq 20); do curl -sI http://site.playground | grep -i '^server'; done | sort | uniq -c"]],
  quiz: ["Why release to 10% first instead of everyone?", "If the new version is bad, only a few users see it, and you find out from real traffic before everyone is affected."] },

"Immutable servers": { lab: "k8s",
  more: ["If you fix a server by hand, it drifts away from what any file describes, and nobody can rebuild it exactly. Immutable means: never patch in place, build a new image and replace.",
    "In Kubernetes, kubectl exec to edit files in a pod is the anti-pattern; the next restart throws your fix away anyway."],
  steps: [["Your site's pods and their ages", "kubectl -n graysoncodes get pods -o wide"],
    ["Every pod of a Deployment runs the same image", "kubectl -n graysoncodes get pods -o custom-columns=POD:.metadata.name,IMAGE:.spec.containers[0].image"],
    ["Prove a pod's changes don't survive: make one, delete it", "kubectl run temp --image=busybox:1.36 -- sh -c 'echo changed > /tmp/x; sleep 3600' && sleep 8 && kubectl delete pod temp"]],
  quiz: ["You fix a bug by editing a file inside a running pod. What happens on the next restart?", "The fix is gone. The pod starts fresh from the image. Fix the image (or config) instead."] },

"Infrastructure as code": { lab: "iac",
  more: ["Code means review (pull requests), history (git log), repeatability (rebuild the same thing) and documentation that can't drift from reality, because it is the reality.",
    "Declarative tools (Kubernetes YAML, Terraform) describe the end state; imperative scripts list steps. Declarative is easier to re-run safely."],
  steps: [["A declarative description", "cat ~/tofu/main.tf"],
    ["Plan shows the difference between code and reality", "cd ~/tofu && tofu init -input=false >/dev/null && tofu plan"],
    ["Ansible describes a machine's state", "cat ~/ansible/site.yml"]],
  quiz: ["Declarative or imperative: \"replicas: 3\"?", "Declarative: it says the end state, not the steps."] },

"Network policies": { lab: "k8s",
  more: ["A NetworkPolicy selects pods and lists which other pods (or namespaces, or IP ranges) may reach them, and on which ports. Once any policy selects a pod, everything not allowed is denied.",
    "k3s enforces them with its built-in network policy controller. A good first one: only the web nginx may talk to the Ledger."],
  steps: [["Any policies yet?", "kubectl get networkpolicy -A"],
    ["Right now every pod can reach every Service. From here:", "curl -sI http://ledger.ledger:5050 | head -1"],
    ["Lock one app so only pods labelled role=friend can reach it, then try from here (you're not a friend)", "kubectl create deployment locked --image=nginxinc/nginx-unprivileged:1.28-alpine && kubectl expose deploy locked --port=80 --target-port=8080 && printf 'apiVersion: networking.k8s.io/v1\\nkind: NetworkPolicy\\nmetadata: {name: locked}\\nspec:\\n  podSelector: {matchLabels: {app: locked}}\\n  policyTypes: [Ingress]\\n  ingress:\\n  - from: [{podSelector: {matchLabels: {role: friend}}}]\\n' | kubectl apply -f - && sleep 15 && (curl -m 5 -sI http://locked.playground >/dev/null && echo reachable || echo 'blocked by the policy (timed out)')"]],
  quiz: ["A pod has no NetworkPolicy selecting it. Who can connect to it?", "Everyone in the cluster. Pods are open by default until a policy selects them."] },

"RBAC: who can do what": { lab: "k8s",
  more: ["Role (in one namespace) or ClusterRole (cluster-wide) = a list of verbs on resources. RoleBinding or ClusterRoleBinding = who gets it: a user, group or ServiceAccount.",
    "This terminal is a live example: a ClusterRoleBinding to \"view\" (read most things), a RoleBinding to \"edit\" in playground only."],
  steps: [["What can this terminal do here?", "kubectl auth can-i --list | head -20"],
    ["And in someone else's namespace?", "kubectl auth can-i create deployments -n ledger; kubectl auth can-i get pods -n ledger"],
    ["The bindings that give it those rights", "kubectl get clusterrolebinding sandbox-learner-view -o yaml | tail -8; kubectl -n playground get rolebinding"]],
  quiz: ["What's the difference between a Role and a ClusterRole?", "A Role works inside one namespace. A ClusterRole is cluster-wide, and can also be granted in just one namespace with a RoleBinding."] },

"Don't run as root": { lab: "security",
  more: ["If an attacker breaks into a container running as root and finds a way out, they're root on the Pi. Running as a normal user, dropping Linux capabilities and blocking privilege escalation all shrink that risk.",
    "Pod Security Standards (baseline, restricted) are the built-in way to enforce this per namespace; your playground uses baseline."],
  steps: [["This terminal's user", "id"],
    ["Its security settings", "kubectl -n sandbox get deploy sandbox -o jsonpath='{.spec.template.spec.securityContext}{\"\\n\"}{.spec.template.spec.containers[0].securityContext}'; echo"],
    ["Which of your apps set runAsNonRoot", "kubectl get deploy -A -o custom-columns=NS:.metadata.namespace,NAME:.metadata.name,NONROOT:.spec.template.spec.securityContext.runAsNonRoot"]],
  quiz: ["What does allowPrivilegeEscalation: false stop?", "Processes in the container gaining more privileges than they started with (for example through setuid programs like sudo)."] },

"Lint your shell scripts": { lab: "bash",
  more: ["The bugs it finds most: unquoted variables (which split on spaces and expand wildcards), [ ] comparisons that break on empty values, and backticks instead of $( ).",
    "Run it in CI on every push so scripts never regress."],
  steps: [["Lint the broken script", "shellcheck ~/scripts/broken.sh"],
    ["Read the fix-it mission", "learn 1"],
    ["Each warning has a wiki page, like SC2086", "shellcheck --wiki-link-count=3 ~/scripts/broken.sh | tail -5"]],
  quiz: ["Why does shellcheck want \"$file\" in quotes?", "Without quotes the value is split on spaces and wildcards expand, so a file name like \"my notes.txt\" becomes two arguments."] },

"Bash strict mode": { lab: "bash",
  more: ["-e: exit when a command fails. -u: treat unset variables as errors (catches typos like $HOEM). -o pipefail: a pipeline fails if any part fails, not just the last.",
    "It has edge cases (commands in if-tests don't trigger -e), but it turns silent failures into loud ones, which is what you want in deploy scripts."],
  steps: [["Without strict mode, the failure is ignored", "bash ~/scripts/deploy.sh; echo \"exit: $?\""],
    ["-u catches a typo'd variable", "bash -c 'set -u; echo \"$HOEM\"'; echo \"exit: $?\""],
    ["pipefail: the pipeline fails if any part fails", "bash -c 'false | true; echo without=$?; set -o pipefail; false | true; echo with=$?'"]],
  quiz: ["Without pipefail, what's the exit code of false | true?", "0, because only the last command (true) counts."] },

"TLS certificates": { lab: "net",
  more: ["A certificate binds a domain name to a public key, signed by a certificate authority your browser trusts. During the TLS handshake the server proves it has the private key, then both sides agree on keys to encrypt the rest.",
    "Your visitors' TLS ends at Cloudflare's edge, which holds the certificate; the tunnel to your Pi is encrypted separately."],
  steps: [["Who issued graysoncodes.org's certificate and when it expires", "openssl s_client -connect graysoncodes.org:443 -servername graysoncodes.org </dev/null 2>/dev/null | openssl x509 -noout -subject -issuer -dates"],
    ["The names it covers", "openssl s_client -connect graysoncodes.org:443 -servername graysoncodes.org </dev/null 2>/dev/null | openssl x509 -noout -ext subjectAltName"],
    ["The handshake, step by step", "curl -svI https://graysoncodes.org 2>&1 | grep -E '^\\* (SSL|TLS|ALPN|Server cert|subject|issuer|expire)' | head"]],
  quiz: ["What does a certificate authority's signature prove?", "That the CA checked whoever got the certificate controls the domain, binding the name to that public key."] },

"How Tailscale works": { lab: "net",
  more: ["Each device has a WireGuard key. Tailscale's coordination server only hands out keys and addresses (100.x.y.z). Devices then connect straight to each other, using NAT traversal tricks; if that fails, traffic goes through an encrypted DERP relay.",
    "MagicDNS and your global nameserver setting are why Tailscale devices use your Pi-hole."],
  steps: [["Your Pi 5's Tailscale address answers from here", "ping -c 3 100.120.223.33"],
    ["Your Pi 4's Tailscale address runs Pi-hole for the whole tailnet", "dig @100.68.50.51 doubleclick.net +short"],
    ["Tailscale's addresses are in a special range", "echo '100.64.0.0/10 is the shared address space Tailscale uses'"]],
  quiz: ["Does your traffic go through Tailscale's servers?", "Usually not. Devices connect directly; only if that's impossible does traffic go through an encrypted relay."] },

"The kubectl cheat sheet": { lab: "k8s",
  more: ["Big time savers: -o wide, -o yaml, -o jsonpath, --sort-by, -l for labels, -w to watch, --dry-run=client -o yaml to generate YAML, and kubectl explain to read the docs for any field.",
    "In this lab, k is already an alias for kubectl and Tab completion works."],
  steps: [["Every resource type and its short name", "kubectl api-resources | head -20"],
    ["Generate YAML instead of writing it", "kubectl create deployment demo --image=nginxinc/nginx-unprivileged:1.28-alpine --dry-run=client -o yaml"],
    ["Docs for any field", "kubectl explain deployment.spec.strategy"]],
  quiz: ["How do you get a starting YAML file for a Deployment without writing it?", "kubectl create deployment NAME --image=IMAGE --dry-run=client -o yaml > file.yaml"] },

"Autoscaling": { lab: "k8s",
  more: ["The HPA reads metrics (CPU by default, from metrics-server) every 15 seconds and changes replicas to keep usage near your target, between min and max. It only works if pods have CPU requests, since usage is measured as a percentage of them.",
    "The Vertical Pod Autoscaler adjusts requests instead, and the Cluster Autoscaler adds nodes (not much use with two Pis)."],
  steps: [["Any autoscalers yet?", "kubectl get hpa -A"],
    ["Make one in the playground", "kubectl create deployment busy --image=nginxinc/nginx-unprivileged:1.28-alpine && kubectl autoscale deployment busy --min=1 --max=3 --cpu=50%"],
    ["Watch it read the metrics", "sleep 30; kubectl get hpa busy"]],
  quiz: ["Why does an HPA need CPU requests on the pods?", "It measures CPU as a percentage of the request; without one there's no percentage to compare to the target."] },

"Init containers": { lab: "k8s",
  more: ["Init containers run in order, each to completion, before the app containers start. If one fails, the pod restarts it. They share volumes with the app, so they can prepare files, and they can use a different image with tools the app doesn't need.",
    "Your off-site backup jobs use one: the app's image makes a safe SQLite snapshot, then restic uploads it."],
  steps: [["Pods that have init containers", "kubectl get pods -A -o jsonpath='{range .items[*]}{.metadata.name}{\": \"}{.spec.initContainers[*].name}{\"\\n\"}{end}' | grep -v ': $'"],
    ["Make one: the app waits until init writes a file", "printf 'apiVersion: v1\\nkind: Pod\\nmetadata: {name: init-demo}\\nspec:\\n  volumes: [{name: shared, emptyDir: {}}]\\n  initContainers:\\n  - {name: prep, image: busybox:1.36, command: [sh, -c, \"echo prepared at $(date) > /s/msg\"], volumeMounts: [{name: shared, mountPath: /s}]}\\n  containers:\\n  - {name: app, image: busybox:1.36, command: [sh, -c, \"cat /s/msg; sleep 3600\"], volumeMounts: [{name: shared, mountPath: /s}]}\\n' | kubectl apply -f -"],
    ["Read what the app saw", "sleep 15; kubectl logs init-demo -c app"]],
  quiz: ["If an init container keeps failing, what status does the pod show?", "Init:Error or Init:CrashLoopBackOff, and the app containers never start."] },

"Kustomize": { lab: "k8s",
  more: ["A kustomization.yaml lists base files and patches: change the image tag, the replicas, add labels or a namespace. kubectl kustomize prints the result; kubectl apply -k applies it.",
    "Helm is templates plus values; Kustomize is plain YAML plus patches. Many teams use both."],
  steps: [["Make a base", "mkdir -p ~/kz && cd ~/kz && kubectl create deployment web --image=nginxinc/nginx-unprivileged:1.28-alpine --dry-run=client -o yaml > deploy.yaml"],
    ["Add a kustomization that changes the image and replicas", "cd ~/kz && printf 'resources: [deploy.yaml]\\nnamePrefix: kz-\\nimages:\\n- {name: nginxinc/nginx-unprivileged, newTag: 1.29-alpine}\\nreplicas:\\n- {name: web, count: 2}\\n' > kustomization.yaml"],
    ["See the result, then apply it", "cd ~/kz && kubectl kustomize . && kubectl apply -k ."]],
  quiz: ["Helm or Kustomize: which one uses templates?", "Helm. Kustomize patches plain YAML without templates."] },

"It's always DNS": { lab: "net",
  more: ["DNS failures look like everything else: timeouts, \"connection refused\" to the wrong IP, an app that works by IP but not by name. Caching makes them come and go.",
    "Quick checks: can you resolve the name? With which server? Does it work by IP? Is the resolver itself up?"],
  steps: [["Can the cluster resolve names?", "dig +short kubernetes.default.svc.cluster.local"],
    ["Which DNS server this pod uses", "grep nameserver /etc/resolv.conf"],
    ["Is CoreDNS healthy?", "kubectl -n kube-system get pods -l k8s-app=kube-dns"]],
  quiz: ["An app works when you use the IP but not the name. What do you suspect?", "DNS: the name isn't resolving, or resolves to the wrong address."] },

"What load average means": { lab: "linux",
  more: ["The three numbers are 1, 5 and 15-minute averages of tasks running or waiting to run, plus (on Linux) tasks waiting on disk. Divide by the CPU count to judge it: on a 4-core Pi, 2.0 is half busy and 8.0 means work is queueing.",
    "A high load with low CPU use usually means slow disk, which on Pis means the SD card."],
  steps: [["The load average and how many CPUs share it", "uptime; nproc"],
    ["Straight from the kernel", "cat /proc/loadavg"],
    ["Make some load and watch it climb", "timeout 30 sh -c 'yes > /dev/null & yes > /dev/null & wait' ; cat /proc/loadavg"]],
  quiz: ["Load average 4.0 on a 4-core Pi: good or bad?", "It's fully busy but not yet queueing. Sustained above 4, things wait."] },

"The USE method": { lab: "linux",
  more: ["For each resource: Utilization (how busy), Saturation (how much is waiting), Errors. CPU: usage %, run queue, —. Memory: used, swapping, OOM kills. Disk: busy %, wait time, I/O errors. Network: throughput, drops, errors.",
    "Going through the list in order finds the bottleneck faster than staring at one graph."],
  steps: [["CPU and memory, once a second (r = waiting to run, si/so = swapping)", "vmstat 1 5"],
    ["Memory", "free -h"],
    ["Network errors and drops", "ip -s link"]],
  quiz: ["In vmstat, the r column is higher than your CPU count. Utilization or saturation?", "Saturation: more tasks want to run than there are CPUs."] },

"OOMKilled pods": { lab: "k8s",
  more: ["When a container goes over its memory limit, the kernel's OOM killer ends it, exit code 137. Kubernetes restarts it, and if it keeps happening you get CrashLoopBackOff.",
    "Fix: find out how much it really needs (kubectl top), raise the limit, or find the leak."],
  steps: [["Pods that restart the most", "kubectl get pods -A --sort-by='.status.containerStatuses[0].restartCount' | tail -5"],
    ["Make one get OOMKilled on purpose", "kubectl run hog --image=busybox:1.36 --restart=Never --overrides='{\"spec\":{\"containers\":[{\"name\":\"hog\",\"image\":\"busybox:1.36\",\"command\":[\"sh\",\"-c\",\"head -c 200m /dev/zero | tail\"],\"resources\":{\"limits\":{\"memory\":\"32Mi\"}}}]}}'"],
    ["See the reason", "sleep 10; kubectl get pod hog; kubectl get pod hog -o jsonpath='{.status.containerStatuses[0].state.terminated.reason}'; echo"]],
  quiz: ["What exit code does an OOMKilled container have?", "137 (128 + 9, killed by SIGKILL)."] },

"Watching for attackers": { lab: "k8s",
  more: ["CrowdSec's agents parse your nginx logs with scenarios (scanning for .env files, brute-forcing logins, crawling 404s). A match makes an alert and a decision (ban this IP for 4 hours). The Cloudflare bouncer pushes decisions to a Worker that shows those IPs a captcha.",
    "It also shares signals with the CrowdSec community, so known-bad IPs get blocked before they reach you."],
  steps: [["CrowdSec's pods", "kubectl get pods -A | grep -i crowdsec"],
    ["What the agent has been reading", "kubectl -n crowdsec logs ds/crowdsec-agent --tail=15 2>/dev/null || kubectl get ds -A | grep -i crowdsec"],
    ["On the real Pi 5 (pi lab): the alerts", "echo 'kubectl -n crowdsec exec deploy/crowdsec-lapi -- cscli alerts list'"]],
  quiz: ["What's the difference between an alert and a decision in CrowdSec?", "An alert records that a scenario matched. A decision is the action taken, like banning the IP for a while."] },

"A pod's life": { lab: "k8s",
  more: ["Pending: accepted but not running yet (scheduling, pulling images). Running: at least one container is running. Succeeded/Failed: all containers have stopped (normal for Jobs). Unknown: the node stopped reporting.",
    "Inside a pod each container is Waiting (with a reason like ImagePullBackOff), Running, or Terminated (with an exit code)."],
  steps: [["The phase of every pod", "kubectl get pods -A -o custom-columns=POD:.metadata.name,PHASE:.status.phase | head -20"],
    ["Watch a pod's whole life", "kubectl run life --image=busybox:1.36 --restart=Never -- sh -c 'sleep 5' && kubectl get pod life -w"],
    ["How it ended", "kubectl get pod life -o jsonpath='{.status.phase} {.status.containerStatuses[0].state.terminated.reason}'; echo"]],
  quiz: ["A Job's pod shows Completed. What phase is that?", "Succeeded: every container exited with code 0."] },

"ClusterIP, NodePort, LoadBalancer": { lab: "k8s",
  more: ["ClusterIP gives a stable virtual IP inside the cluster. NodePort adds a port (30000-32767) on every node that forwards to it. LoadBalancer asks for an outside IP; k3s's ServiceLB fakes one by opening the port on the nodes.",
    "Your apps use NodePorts over Tailscale, and the public site uses ClusterIP behind the Cloudflare tunnel."],
  steps: [["All your NodePorts", "kubectl get svc -A | grep -i nodeport"],
    ["Make a ClusterIP Service in the playground and reach it", "kubectl create deployment svcdemo --image=nginxinc/nginx-unprivileged:1.28-alpine && kubectl expose deploy svcdemo --port=80 --target-port=8080 && sleep 10 && curl -sI http://svcdemo.playground | head -1"],
    ["The endpoints behind it", "kubectl get endpoints svcdemo"]],
  quiz: ["Which Service type would you use for a database only other pods should reach?", "ClusterIP."] },

"Velero backs up a cluster": { lab: "backups",
  more: ["Velero exports Kubernetes objects as JSON and backs up volumes (with restic/kopia or snapshots) to object storage. You can schedule backups and restore a namespace, even into a new cluster.",
    "Your nightly restic jobs cover the important data. Velero would add the YAML and make disaster recovery one command."],
  steps: [["The same engine Velero uses for files: restic", "restic version"],
    ["Back up, then list", "restic -r ~/backup-repo init 2>/dev/null; restic -r ~/backup-repo backup ~/data && restic -r ~/backup-repo snapshots"],
    ["The volumes Velero would protect on your cluster", "kubectl get pvc -A -o custom-columns=NS:.metadata.namespace,NAME:.metadata.name,SIZE:.spec.resources.requests.storage"]],
  quiz: ["What does Velero back up that your restic jobs don't?", "The Kubernetes objects themselves (Deployments, Services, ConfigMaps...), so a whole namespace can be restored."] },

"Loki: logs like Prometheus": { lab: "k8s",
  more: ["Loki doesn't index the log text, only labels (namespace, app, pod). Queries pick streams by label and then grep through them, which keeps it cheap on small hardware.",
    "An agent (Promtail or Grafana Alloy) on each node tails the container log files, like CrowdSec's agent does."],
  steps: [["One app's logs from all its pods", "kubectl -n graysoncodes logs -l app=web --prefix --since=1h --tail=5"],
    ["The labels Loki would index", "kubectl -n graysoncodes get pods --show-labels"],
    ["Searching log text the slow way", "kubectl -n graysoncodes logs deploy/web --tail=1000 | grep -c ' 404 '"]],
  quiz: ["Why is Loki cheaper than a full-text log search engine?", "It only indexes labels, not the log text, and stores compressed chunks."] },

"What OpenTelemetry is": { lab: "linux",
  more: ["Traces follow one request through every service it touches, as spans with timings. Metrics are numbers over time. Logs are events. OpenTelemetry gives one SDK and protocol (OTLP) for all three, and you choose where to send them (Grafana Tempo, Jaeger, Prometheus).",
    "For a Flask app it's a few lines plus auto-instrumentation."],
  steps: [["Python is here: check the version", "python3 --version"],
    ["A span is basically a timed, named block. Try a homemade one", "python3 -c \"import time;t=time.time();sum(range(10**6));print(f'span compute took {(time.time()-t)*1000:.1f} ms')\""],
    ["Real OTel would export that as OTLP to a collector", "echo 'pip install opentelemetry-distro && opentelemetry-instrument flask run'"]],
  quiz: ["What's a trace made of?", "Spans: timed operations with parent/child links, following one request across services."] },

"Shell tools you'll use forever": { lab: "linux",
  more: ["grep finds lines, find finds files, xargs turns lines into arguments, awk picks columns and does sums, sort | uniq -c counts, and pipes glue them together.",
    "Learn them on a log file and you can answer most \"what happened?\" questions on any server."],
  steps: [["Count requests per status code", "awk '{print $9}' ~/practice/logs/access.log | sort | uniq -c | sort -rn"],
    ["Find files and count their lines", "find ~/practice -type f -name '*.conf' | xargs wc -l"],
    ["Your missions in this lab", "learn"]],
  quiz: ["What does sort | uniq -c do?", "Counts how many times each distinct line appears (uniq only merges neighbours, so sort first)."] },

"The big picture": { lab: "k8s",
  more: ["You talk to the API server; it stores everything in the datastore. The scheduler assigns new pods to nodes. Controllers (Deployment, ReplicaSet, Job...) keep reality matching what's stored. On each node the kubelet starts containers through containerd, and kube-proxy sets up Service networking.",
    "In k3s all of those run inside the one k3s process on the Pi 5; the Pi 4 runs the agent half."],
  steps: [["The API server's health checks", "kubectl get --raw='/readyz?verbose' | tail -8"],
    ["The nodes and their roles", "kubectl get nodes -o wide"],
    ["The system add-ons", "kubectl -n kube-system get pods -o wide"]],
  quiz: ["Which component decides which node a new pod runs on?", "The scheduler."] },

"What DevOps actually means": { lab: "k8s",
  more: ["Common ideas: automate the boring parts, ship small changes often, measure everything, share responsibility for production, and learn from failures without blame. Tools follow from those ideas, not the other way round.",
    "In your homelab you write the code, build it in CI, deploy it, watch it, back it up and fix it at 2am. That's the whole loop."],
  steps: [["Everything you run, counted", "kubectl get all -A --no-headers | wc -l"],
    ["Namespaces = your apps", "kubectl get ns"],
    ["How long things have been up", "kubectl get pods -A --sort-by=.metadata.creationTimestamp | head -10"]],
  quiz: ["Name three practices that count as DevOps.", "Any three: CI/CD, infrastructure as code, monitoring and alerting, blameless postmortems, small frequent releases, automation, shared on-call."] },
};
